    private static Compilation CreateCompilation(string assemblyName, string source, params MetadataReference[] extraReferences)
    {
        var references = RazorVueMetadataReferences.Create(extraReferences);

        return CSharpCompilation.Create(
            assemblyName,
            RazorVueMetadataReferences.CreateSyntaxTrees(source),
            references,
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));
    }

    private static (Compilation Compilation, RazorVueRazorSourceGeneratorDocumentInput Input) CreateRazorSgTailBridgeInput(
        string assemblyName,
        string documentPath,
        string documentText,
        string componentSource,
        string rootNamespace,
        string? importsText = null)
    {
        var (compilation, _, codeDocument, csharpDocument) = CreateAlignedRazorComponentCompilationCore(
            assemblyName,
            documentPath,
            documentText,
            componentSource,
            rootNamespace,
            importsText);

        return (compilation, new RazorVueRazorSourceGeneratorDocumentInput(
            Path.GetFileName(documentPath) + ".g.cs",
            codeDocument,
            csharpDocument));
    }

    private static Compilation CreateAlignedRazorComponentCompilation(
        string assemblyName,
        string documentPath,
        string documentText,
        string componentSource,
        string rootNamespace,
        string? importsText = null)
        => CreateAlignedRazorComponentCompilationCore(
                assemblyName,
                documentPath,
                documentText,
                componentSource,
                rootNamespace,
                importsText)
            .Compilation;

    private static (
        Compilation Compilation,
        CSharpParseOptions ParseOptions,
        RazorCodeDocument CodeDocument,
        RazorCSharpDocument CSharpDocument) CreateAlignedRazorComponentCompilationCore(
        string assemblyName,
        string documentPath,
        string documentText,
        string componentSource,
        string rootNamespace,
        string? importsText)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.Preview);
        var baseCompilation = CSharpCompilation.Create(
            assemblyName: assemblyName,
            syntaxTrees:
            [
                CSharpSyntaxTree.ParseText(
                    """
                    global using static ECMAScript.Vue3;
                    global using ECMAScript.VueContract;
                    global using Microsoft.AspNetCore.Components;
                    """,
                    options: parseOptions,
                    path: "RazorVueTestGlobalUsings.g.cs"),
                CSharpSyntaxTree.ParseText(
                    """
                    using System;

                    namespace ECMAScript
                    {
                        [AttributeUsage(AttributeTargets.Class, Inherited = false)]
                        public sealed class ECMAScriptModuleAttribute : Attribute
                        {
                            public ECMAScriptModuleAttribute() { }
                            public ECMAScriptModuleAttribute(string import) { }
                        }
                    }
                    """,
                    options: parseOptions,
                    path: "ECMAScriptModuleAttribute.cs"),
                CSharpSyntaxTree.ParseText(
                    componentSource,
                    options: parseOptions,
                    path: Path.GetFileNameWithoutExtension(documentPath) + ".razor.cs")
            ],
            references: RazorVueMetadataReferences.Create(),
            options: new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        var projectEngine = RazorVueRazorCodeDocumentProvider.CreateProjectEngine(
            documentPath,
            parseOptions,
            rootNamespace: rootNamespace);
        var tagHelpers = RazorVueRazorCodeDocumentProvider.DiscoverTagHelpers(projectEngine, baseCompilation);
        var importDocuments = string.IsNullOrWhiteSpace(importsText)
            ? ImmutableArray<RazorSourceDocument>.Empty
            : ImmutableArray.Create(
                RazorVueRazorCodeDocumentProvider.CreateSourceDocument(
                    new RazorVueRazorDocument(Path.Combine(Path.GetDirectoryName(documentPath)!, "_Imports.razor"), SourceText.From(importsText))));
        var codeDocument = projectEngine.Process(
            RazorVueRazorCodeDocumentProvider.CreateSourceDocument(
                new RazorVueRazorDocument(documentPath, SourceText.From(documentText))),
            RazorFileKind.Component,
            importDocuments,
            tagHelpers.Length == 0 ? null : TagHelperCollection.Create(tagHelpers));
        var csharpDocument = RazorVueRazorCodeDocumentProvider.GetRequiredCSharpDocument(codeDocument);

        var compilation = baseCompilation.AddSyntaxTrees(
            CSharpSyntaxTree.ParseText(
                csharpDocument.Text,
                options: parseOptions,
                path: Path.GetFileName(documentPath) + ".g.cs"));
        var errors = compilation.GetDiagnostics()
            .Where(static diagnostic => diagnostic.Severity == DiagnosticSeverity.Error)
            .ToArray();
        Assert.AreEqual(
            0,
            errors.Length,
            string.Join(Environment.NewLine, errors.Select(static diagnostic => diagnostic.ToString()))
            + Environment.NewLine
            + csharpDocument.Text);

        return (compilation, parseOptions, codeDocument, csharpDocument);
    }

    private static Compilation InjectCarrierCompilation(Compilation compilation, string documentPath, string documentText)
    {
        var componentTree = compilation.SyntaxTrees.Single(static tree => tree.FilePath.EndsWith(".razor.cs", StringComparison.Ordinal));
        var updatedSource = InjectCarrierAttribute(componentTree.ToString(), documentPath, documentText);
        return compilation.ReplaceSyntaxTree(
            componentTree,
            CSharpSyntaxTree.ParseText(
                updatedSource,
                options: (CSharpParseOptions?)componentTree.Options,
                path: componentTree.FilePath));
    }

    private static string InjectCarrierAttribute(string componentSource, string documentPath, string documentText)
    {
        if (componentSource.Contains("RazorVueRazorIrCarrierAttribute", StringComparison.Ordinal))
            return componentSource;

        const string marker = "[ECMAScript.ECMAScriptModule(\"./components/todo-app\")]";
        var replacement = string.Join(
            Environment.NewLine,
            marker,
            "    [Jazor.RazorVue.Runtime.RazorVueRazorIrCarrierAttribute(",
            "        " + ToVerbatimLiteral(documentPath) + ",",
            "        " + ToVerbatimLiteral(JsonSerializer.Serialize(Array.Empty<object>())) + ",",
            "        " + ToVerbatimLiteral(documentText) + ")]");

        return componentSource.Replace(marker, replacement, StringComparison.Ordinal);
    }

    private static string ToVerbatimLiteral(string text)
        => "@\"" + text.Replace("\"", "\"\"", StringComparison.Ordinal) + "\"";

    private static Compilation RunGenerator(Compilation compilation, out string generatedSource)
    {
        var (outputCompilation, runResult) = RunGeneratorWithResult(compilation);
        generatedSource = GetGeneratedSource(runResult, "Jazor.Generated.ModuleCatalog.g.cs");

        return outputCompilation;
    }

    private static string GetGeneratedSource(GeneratorDriverRunResult runResult, string hintName)
        => runResult.Results
            .SelectMany(static result => result.GeneratedSources)
            .Single(source => source.HintName == hintName)
            .SourceText
            .ToString();

    private static (Compilation OutputCompilation, GeneratorDriverRunResult RunResult) RunGeneratorWithResult(Compilation compilation)
    {
        ISourceGenerator[] generators =
        [
            new ESGenerator().AsSourceGenerator()
        ];

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators,
            parseOptions: (CSharpParseOptions?)compilation.SyntaxTrees.FirstOrDefault()?.Options);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out var outputCompilation, out _);

        var runResult = driver.GetRunResult();
        return (outputCompilation, runResult);
    }

    private static (Compilation OutputCompilation, GeneratorDriverRunResult RunResult) RunAllGeneratorsWithResult(
        Compilation compilation,
        string? razorVueOutputMode = "legacy",
        RazorVueGenerator? razorVueGenerator = null,
        bool enableRazorSgIntegration = false)
    {
        ISourceGenerator[] generators =
        [
            new ESGenerator().AsSourceGenerator(),
            (razorVueGenerator ?? new RazorVueGenerator()).AsSourceGenerator()
        ];

        GeneratorDriver driver = CSharpGeneratorDriver.Create(
            generators,
            parseOptions: (CSharpParseOptions?)compilation.SyntaxTrees.FirstOrDefault()?.Options,
            optionsProvider: CreateAnalyzerConfigOptionsProvider(razorVueOutputMode, enableRazorSgIntegration),
            driverOptions: default);
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out var outputCompilation, out _);

        var runResult = driver.GetRunResult();
        return (outputCompilation, runResult);
    }

    private static RazorVueGenerator CreateRazorSgIntegrationTestGenerator(
        RazorSourceGeneratorBootstrapTrace bootstrapTrace,
        Func<RazorSourceGeneratorCompatibilityProbeResult>? compatibilityProbeFactory = null)
        => new(
            static () => new RazorVuePipeline(RazorVueRazorDocumentSemanticFrontend.Instance, RazorVuePreferredTemplateFrontend.Instance),
            static () => new RazorVueSfcPipeline(RazorVueRazorDocumentSemanticFrontend.Instance, RazorVuePreferredTemplateFrontend.Instance),
            compatibilityProbeFactory ?? (static () => RazorSourceGeneratorCompatibilityProbe.CollectCurrent()),
            _ => bootstrapTrace);

    private static RazorSourceGeneratorBootstrapTrace CreateBootstrapTrace(
        bool hasAttempted,
        bool isInstalled,
        bool tailOutputRegistered,
        bool currentContextKeyAvailable = true,
        bool? tailOutputRegisteredForCurrentContext = null,
        string tailOutputRegistrationKind = "implementation-source-output",
        bool patchFailed = false,
        string? failure = null)
        => new(
            HasAttempted: hasAttempted,
            IsInstalled: isInstalled,
            RazorAssemblyObserved: isInstalled || patchFailed,
            PatchAttempted: isInstalled || patchFailed,
            GeneratorTypeFound: isInstalled,
            InitializeMethodFound: isInstalled,
            PostfixMethodFound: isInstalled,
            PatchSucceeded: isInstalled,
            PatchFailed: patchFailed,
            PostfixInvoked: tailOutputRegistered,
            HostOutputHookInstalled: tailOutputRegistered,
            HostOutputObserved: tailOutputRegistered,
            TailOutputRegistered: tailOutputRegistered,
            CurrentContextKeyAvailable: currentContextKeyAvailable,
            TailOutputRegisteredForCurrentContext: tailOutputRegisteredForCurrentContext ?? tailOutputRegistered,
            TailOutputRegistrationKind: tailOutputRegistered ? tailOutputRegistrationKind : string.Empty,
            TestHookObserved: false,
            Failure: failure);

    private static RazorSourceGeneratorCompatibilityProbeResult CreateSupportedRazorSgCompatibilityProbe()
        => RazorSourceGeneratorCompatibilityProbeResult.Succeed(new RazorSourceGeneratorCompatibilityShape(
            AssemblyPath: "ignored",
            AssemblyVersion: "10.0.0.0",
            ModuleVersionId: "ignored",
            TypeFullName: "Microsoft.NET.Sdk.Razor.SourceGenerators.RazorSourceGenerator",
            ImplementsIncrementalGenerator: true,
            InitializeMethodName: "Initialize",
            InitializeContextParameterType: "Microsoft.CodeAnalysis.IncrementalGeneratorInitializationContext",
            InitializeMethodReturnType: "System.Void",
            InitializeMethodIsPublic: true,
            InitializeMethodIsStatic: false,
            InitializeMethodIlLength: 1,
            InitializeMethodIlSha256: "diagnostic-only",
            DeclaredMethodNames: ["ComputeRazorSourceGeneratorOptions", "Initialize"]));

    private static AnalyzerConfigOptionsProvider CreateAnalyzerConfigOptionsProvider(string? razorVueOutputMode, bool enableRazorSgIntegration)
    {
        var options = new Dictionary<string, string>(StringComparer.Ordinal);
        if (razorVueOutputMode is not null)
        {
            options["build_property.JazorRazorVueOutputMode"] = razorVueOutputMode;
        }

        if (enableRazorSgIntegration)
        {
            options["build_property.JazorRazorVueEnableRazorSgIntegration"] = "true";
        }

        return new TestAnalyzerConfigOptionsProvider(options);
    }

    private sealed class TestAnalyzerConfigOptionsProvider(IReadOnlyDictionary<string, string> globalOptions) : AnalyzerConfigOptionsProvider
    {
        private readonly AnalyzerConfigOptions _globalOptions = new TestAnalyzerConfigOptions(globalOptions);
        private static readonly AnalyzerConfigOptions EmptyOptions = new TestAnalyzerConfigOptions(new Dictionary<string, string>(StringComparer.Ordinal));

        public override AnalyzerConfigOptions GlobalOptions => _globalOptions;

        public override AnalyzerConfigOptions GetOptions(SyntaxTree tree)
            => EmptyOptions;

        public override AnalyzerConfigOptions GetOptions(AdditionalText textFile)
            => EmptyOptions;
    }

    private sealed class TestAnalyzerConfigOptions(IReadOnlyDictionary<string, string> values) : AnalyzerConfigOptions
    {
        private readonly IReadOnlyDictionary<string, string> _values = values;

        public override bool TryGetValue(string key, out string value)
            => _values.TryGetValue(key, out value!);
    }

    private sealed class RazorDocumentEchoTemplateFrontend : IRazorVueTemplateFrontend
    {
        public string Name => "Jazor.RazorVue.Test.ESGeneratorTests.RazorDocumentEchoTemplateFrontend";

        public RazorVueRenderFragment CreateRenderTree(RazorVueCompilationContext context, RazorVueSemanticSnapshot snapshot)
        {
            Assert.IsNotNull(snapshot.RazorIrCarrier);
            return new RazorVueRenderFragment(
                ImmutableArray.Create<RazorVueRenderNode>(
                    new RazorVueTextNode(snapshot.RazorIrCarrier.DocumentText.Trim(), ImmutableArray<RazorVueSourceOrigin>.Empty)));
        }
    }
}
